inline constexpr std::size_t kRegisteredStateGraphEdgeCount =
    sizeof(kRegisteredStateGraphEdges) / sizeof(kRegisteredStateGraphEdges[0]);

inline std::size_t stateGraphRegionCount() {
    std::size_t count = 0;
    for (const RegisteredStateGraphRow& row : kRegisteredStateGraph)
        if (row.order == 0) ++count;
    return count;
}

inline std::size_t stateGraphClassCount() {
    std::size_t count = 0;
    for (std::size_t i = 0; i < kRegisteredStateGraphCount; ++i) {
        bool seen = false;
        for (std::size_t j = 0; j < i; ++j)
            if (kRegisteredStateGraph[j].className ==
                kRegisteredStateGraph[i].className) {
                seen = true;
                break;
            }
        if (!seen) ++count;
    }
    return count;
}

inline const char* recoveredInitialState(std::string_view className) {
    for (const RegisteredStateGraphRow& row : kRegisteredStateGraph)
        if (row.className == className && row.isInitial != 0)
            return row.stateName.data();
    return nullptr;
}

inline bool graphOrdersState(std::string_view className,
                              std::string_view stateName) {
    for (const RegisteredStateGraphRow& row : kRegisteredStateGraph)
        if (row.className == className && row.stateName == stateName)
            return true;
    return false;
}

inline std::size_t graphStateCount(std::string_view className) {
    for (const RegisteredStateGraphRow& row : kRegisteredStateGraph)
        if (row.className == className) return row.stateCount;
    return 0;
}

inline std::size_t graphEdgeCount(std::string_view className) {
    std::size_t count = 0;
    for (const RegisteredStateGraphEdge& edge : kRegisteredStateGraphEdges)
        if (edge.className == className) ++count;
    return count;
}

